-- ============================================================================
-- 093_哈兰NPC静态刷点_原版真实坐标.sql
--
-- 目的：把哈兰(Halaa)镇里的商人/研究员/军需官/卫兵改成【永久 DB 刷点】（静态 guid），
--       不再依赖 dbscripts_on_event 11503/11504 的【临时召唤】。
--
-- 为什么：那 40 个 NPC 原来是占领时由原版脚本临时召唤的（动态 guid、不落库）：
--   · 网格卸载（玩家走开 2 分钟，GridCleanUpDelay）就整批消失，而脚本只在占领那一刻跑过一次；
--   · opvp 代码本身假设它们是永久刷点（卫兵战死靠 GetRespawnCoord() 记位复活、DespawnVendors 按 guid 处理）；
--   · guid 是动态的，一旦 NPC 消失，代码手里记的 guid 就全是死的。
--
-- 坐标来源：dbscripts_on_event 11503（部落）/ 11504（联盟）里 command=10 的 40 行【原版真实坐标】，
--           逐值生成，未做任何估算（当初否掉旧方案就是因为坐标是估的）。
--
-- 布局：guid 9000001-9000015 部落卫兵(18192) ｜ 9000016-9000030 联盟卫兵(18256)
--       guid 9000031-9000035 部落商人/研究员/军需官 ｜ 9000036-9000040 联盟商人/研究员/军需官
--       双方卫兵共用同一批岗哨坐标（同位置成对），与脚本一致。
--
-- 复活时间：2592000/2592000 秒（30 天 = 核心不自己复活），复活完全交给 opvp ——"卫兵战死后 5 分钟（围城时 1 小时）在原位把当方卫兵补回来（RespawnSoldier）。
-- 幂等：先删 guid 段及其附属表，再插入；可反复执行。
-- ============================================================================

USE tbcmangos;

DELETE FROM creature                  WHERE guid BETWEEN 9000001 AND 9000040;
DELETE FROM creature_addon            WHERE guid BETWEEN 9000001 AND 9000040;
DELETE FROM creature_movement         WHERE id   BETWEEN 9000001 AND 9000040;
DELETE FROM creature_conditional_spawn WHERE guid BETWEEN 9000001 AND 9000040;
DELETE FROM spawn_group_spawn         WHERE guid BETWEEN 9000001 AND 9000040;
DELETE FROM game_event_creature       WHERE guid BETWEEN 9000001 AND 9000040;


-- 校验：应恰好 40 行（15 部落卫兵 + 15 联盟卫兵 + 5 部落商人 + 5 联盟商人）
SELECT id, COUNT(*) AS rows_cnt FROM creature WHERE guid BETWEEN 9000001 AND 9000040 GROUP BY id ORDER BY id;
